def brute_force(graph: List[List[int]], initial: List[int]) -> int:
    # Remove each candidate in turn and BFS the spread from the remaining initial nodes.
    n = len(graph)
    best, best_count = -1, n + 1
    for cand in sorted(initial):
        seen = set(x for x in initial if x != cand)
        stack = list(seen)
        while stack:
            u = stack.pop()
            for v in range(n):
                if graph[u][v] and v not in seen:
                    seen.add(v)
                    stack.append(v)
        if len(seen) < best_count:
            best, best_count = cand, len(seen)
    return best

