class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path halving
                x = parent[x]
            return x

        for i in range(n):
            for j in range(i + 1, n):
                if graph[i][j]:
                    parent[find(i)] = find(j)

        size = Counter(find(i) for i in range(n))
        infected = Counter(find(i) for i in initial)
        best, saved = min(initial), 0
        for node in sorted(initial):  # ascending: ties keep the smaller index
            root = find(node)
            if infected[root] == 1 and size[root] > saved:
                best, saved = node, size[root]
        return best

