        for qi in order:
            p, q, limit = queries[qi]
            while j < len(edges) and edges[j][2] < limit:
                u, v, _ = edges[j]
                parent[find(u)] = find(v)  # every edge lighter than this limit is glued in
                j += 1
            ans[qi] = find(p) == find(q)
        return ans

